#!/usr/bin/env python3
import json
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
MAN=json.loads((ROOT/'release-manifest-v0.43.0.json').read_text())
REG=json.loads((ROOT/'registry/workspace-product-record-v0.43.0.json').read_text())
PREV=json.loads((ROOT/'history/release-manifest-v0.42.0.json').read_text())
MAIN=(ROOT/'wordpress/sustainable-catalyst-workspace/sustainable-catalyst-workspace.php').read_text()
PHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace.php').read_text()
REGPHP=(ROOT/'wordpress/sustainable-catalyst-workspace/includes/class-sc-workspace-registry.php').read_text()
JS=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/workspace-v0.43.0.js').read_text()
COLL=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-collections-v1.js').read_text()
SEARCH=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-knowledge-search-v1.js').read_text()
IK=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-integrated-knowledge-v1.js').read_text()
NAV=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-research-navigation-v1.js').read_text()
PORT=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-portability-v1.js').read_text()
REVIEW=(ROOT/'wordpress/sustainable-catalyst-workspace/assets/js/sc-workspace-notebook-review-provenance-v1.js').read_text()
def c(x,l):
 if not x: raise SystemExit('FAIL - '+l)
 print('PASS - '+l)
c('Version: 0.43.0' in MAIN,'plugin version')
c((MAN['version'],MAN['previous_version'],MAN['release_name'])==('0.43.0','0.42.0','Research Collections & Dynamic Views'),'manifest release lineage')
c((MAN['storage_schema_version'],MAN['project_schema'],MAN['export_schema'])==(35,'sc-workspace-project/20.0','sc-workspace-project-export/20.0'),'schema-stable storage 35 / project 20 / export 20')
c(not MAN['schema_migration_required'] and MAN['migration']['schema_stable'] and MAN['migration']['collections_views_only_release'] and not MAN['migration']['canonical_data_rewrite'],'schema-stable collections/views boundary')
c(PREV['migration']['retrieval_only_release'],'v0.42 Advanced Retrieval history retained')
c('/wp-json/sc-workspace/v1/research-collections-contract' in MAN['rest_routes'] and "'/research-collections-contract'" in PHP,'Research Collections REST contract')
c(MAN['research_collection_schema']=='sc-workspace-research-collection/1.0' and MAN['research_view_schema']=='sc-workspace-research-view/1.0','Research Collection/View schemas')
rc=MAN['research_collections']
c(rc['corpus']=='derived-integrated-knowledge-index' and rc['membership']=='dynamic-query-evaluation','derived dynamic collection membership')
c(rc['storage']=='browser-local-definitions-only' and not rc['canonical_records_copied'] and not rc['membership_snapshots_stored'],'definitions only / no copied membership')
c(rc['builtin_views']==['sources','evidence','decisions','analysis','notebooks','documented'] and rc['project_lens_preserved_when_applying_builtin_view'],'project-aware built-in research views')
c(rc['view_groupings']==['none','project','kind','subtype','origin'] and rc['view_densities']==['compact','comfortable'],'saved view presentation controls')
c(not rc['automatic_ai'] and not rc['semantic_inference'] and not rc['server_collection_index'],'no AI / semantic inference / server collection index')
c(all(x in COLL for x in ('function smartCollection','function researchView','function builtinCriteria','function evaluate(entries,collection,state,searchApi)','function group(rows','function dashboard(entries,state,searchApi,current={})')),'Research Collections runtime')
c(all(x in PHP for x in ('data-scw-smart-collection','data-scw-research-view','data-scw-view-group','data-scw-view-density','data-scw-dashboard-sources','data-scw-dynamic-preview')),'Research Collections presentation')
c(all(x in JS for x in ('loadResearchCollections','persistResearchCollections','loadResearchViews','persistResearchViews','renderResearchCollections(all)')),'browser-local collection/view integration')
g=MAN['governance']
c(g['research_collections_derived_from_knowledge_search'] and g['research_collections_browser_local_definitions'] and not g['research_collections_duplicate_canonical_content'],'derived collections / no duplicate canonical store')
c(g['research_collections_saved_views_local_only'] and not g['research_collections_saved_views_mutate_projects'],'saved views do not mutate projects')
c(g['research_collections_dashboard_derived'] and not g['research_collections_hidden_dashboard_score'],'derived dashboard / no hidden score')
c('function search(entries,prefs={},state={})' in SEARCH and 'function related(target,entries,state)' in SEARCH,'v0.42 Advanced Retrieval runtime retained')
c('function derive(state)' in IK and 'duplicatesCanonicalContent:false' in IK,'v0.40 Integrated Knowledge retained')
c('function areaForView(view)' in NAV and all(x in NAV for x in ("start:{label:'Start'","projects:{label:'Projects'","research:{label:'Research'","review:{label:'Review'","exchange:{label:'Exchange'")),'v0.41 unified navigation retained')
c('expectedRevision' in PORT and 'silentLastWriteWins:false' in PORT,'v0.38 conflict-safe notebook sync retained')
c(all(x in REVIEW for x in ('buildReview','buildReconciliation','shadowProvenanceDatabase:false')),'v0.39 Notebook Review & Provenance retained')
c((REG['public_version'],REG['previous_version'])==('0.43.0','0.42.0'),'registry lineage')
c("BACKUP_KEY = 'sc_workspace_registry_backup_v0430'" in REGPHP and 'LEGACY_PENDING_KEY_V0420' in REGPHP,'registry retry lineage')
c((ROOT/'history/release-manifest-v0.42.0.json').exists() and (ROOT/'history/workspace-product-record-v0.42.0.json').exists(),'v0.42 history preserved')
files=list((ROOT/'schemas').glob('*.json'))+[ROOT/'release-manifest-v0.43.0.json',ROOT/'registry/workspace-product-record-v0.43.0.json']
for p in files: json.loads(p.read_text())
print(f'PASS - {len(files)} JSON schema/release records')
print('VALIDATION PASSED: Sustainable Catalyst Workspace v0.43.0 — Research Collections & Dynamic Views')
